def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    alive_opps = []
    prev_bids = []
    prev_urgent_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 4:
                    prev_urgent_bids.append(b)

    if budget <= 0:
        return 0.0

    competitors = len(alive_opps) + 1
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < competitors
    very_tight = expected_units < max(1.2, competitors - 1)

    max_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else max_prev
    urgent_anchor = max(prev_urgent_bids) if prev_urgent_bids else max_prev

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1
    if very_tight:
        danger += 2
    elif scarcity:
        danger += 1
    if day >= 8:
        danger += 1

    if not alive_opps:
        return round(min(budget, DAILY_SALARY * 0.35), 2)

    if danger >= 6:
        target = max(urgent_anchor + 2.0, 0.92 * DAILY_SALARY)
        if max_prev > DAILY_SALARY:
            target = max(target, second_prev + 1.5)
        target = min(target, budget)
    elif danger >= 4:
        target = max(0.72 * DAILY_SALARY, min(max_prev + 1.25, DAILY_SALARY * 1.02))
        if scarcity:
            target = max(target, 0.82 * DAILY_SALARY)
        target = min(target, budget)
    elif danger >= 2:
        if scarcity:
            target = max(0.48 * DAILY_SALARY, min(second_prev * 0.55 + 6.0, DAILY_SALARY * 0.78))
        else:
            target = 0.34 * DAILY_SALARY
        target = min(target, budget)
    else:
        if max_prev >= 110:
            target = 0.18 * DAILY_SALARY
        elif scarcity:
            target = 0.28 * DAILY_SALARY
        else:
            target = 0.12 * DAILY_SALARY
        target = min(target, budget)

    reserve = 0.0
    if hp > 4 and no_water == 0 and day <= 7:
        reserve = DAILY_SALARY * 0.15
    if budget - target < reserve:
        target = max(0.0, budget - reserve)

    if hp <= 2 or no_water >= 2:
        target = max(target, min(budget, DAILY_SALARY * 0.9))

    return round(max(0.0, min(budget, target)), 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and their yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid', None)
            alive_opps.append((opp_id, opp, bid))

    if not alive_opps:
        # No one to compete with; conserve budget
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for _, _, bid in alive_opps:
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Supply scarcity pressure: fewer units means higher contest intensity
    # Use explicit int conversions for any indexing (none used here).
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Compute a target bid based on yesterday's aggressiveness by survivors
    # If someone bid very high yesterday, we must match/beat to prevent them from securing water.
    high_thresh = DAILY_SALARY * 0.85
    mid_thresh = DAILY_SALARY * 0.55

    target = DAILY_SALARY * (0.45 + 0.35 * scarcity)

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        lowest_prev = min(yesterday_bids)

        if highest_prev >= high_thresh:
            # Someone was extremely aggressive; bid to contest.
            if my_status.get('hp', 0) <= 2:
                target = DAILY_SALARY * (0.95 - 0.05 * scarcity)
            elif my_status.get('hp', 0) <= 3:
                target = DAILY_SALARY * (0.75 + 0.15 * scarcity)
            else:
                target = max(target, highest_prev + 1.0)
        elif highest_prev >= mid_thresh:
            # Moderate aggression; slightly over the median/typical range.
            target = max(target, (highest_prev * 0.9) + (1.0 * scarcity))
        else:
            # Low bids yesterday; we can undercut slightly but still secure.
            target = max(target, lowest_prev + 2.0 * (1.0 - scarcity))

    # If we're in danger (low hp or many no-water days), increase bid.
    hp = float(my_status.get('hp', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    if hp <= 1.0 or no_water_days >= 3:
        target = max(target, DAILY_SALARY * (0.85 + 0.1 * scarcity))
    elif hp <= 3.0:
        target = max(target, DAILY_SALARY * (0.6 + 0.15 * scarcity))

    # Clamp by budget and keep within a reasonable cap relative to supply
    budget = float(my_status.get('budget', 0))
    if budget <= 0:
        return 0.0

    # Convert target to feasible bid: never exceed budget.
    bid = float(min(budget, target))

    # Additional cap: avoid extreme bids beyond what supply range suggests.
    # Since supply max is 25, water units are at most floor(supply/9) ~ 2.
    # Keep bid around at most 2.2 * salary fraction.
    bid_cap = DAILY_SALARY * 1.5
    bid = min(bid, bid_cap)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

